let image_paths_env = std::env::var("IMAGE_PATHS").expect("IMAGE_PATHS not set");
let output_path = std::env::var("OUTPUT_PATH").expect("OUTPUT_PATH not set");
let image_paths: Vec<String> = image_paths_env.split(',').map(|s| s.trim().to_string()).collect();
if image_paths.is_empty() {
    panic!("No image paths provided");
}

use std::process::Command;
let mut cmd = Command::new("topdf");
cmd.arg("-o").arg(&output_path);
for p in &image_paths {
    cmd.arg(p);
}
let status = cmd.status().expect("failed to execute topdf");
if !status.success() {
    panic!("topdf command failed");
}
